//! ConnectRPC service implementations.
//!
//! These services implement the protobuf service traits generated by
//! `connectrpc-build` from the `.proto` definitions in `aos-proto`.
//! Each service delegates to the existing server business logic (store,
//! views, build manager, etc.) rather than duplicating it:
//!
//! - [`auth`] — `AuthService`: provisioning-secret -> JWT exchange
//!   (RPC twin of `POST /oauth2/token`).
//! - [`cache`] — `CacheService`: cache info, narinfo, query-missing, and
//!   streamed NAR upload/download/pack-upload.
//! - [`build`] — `BuildService`: server-streaming build and build-closure.
//! - [`gc`] — `GcService`: TTL expiry, eviction, and store GC.
//!
//! The services are registered on the shared axum router by
//! [`crate::routes::router`], so REST and RPC traffic share one listener.
//! The `require_rpc_*` helpers in this module mirror the REST auth
//! extractors: they pull the `Authorization: Bearer` JWT out of the RPC
//! [`Context`] and enforce view/permission checks, mapping failures to
//! `unauthenticated` / `permission_denied` ConnectRPC error codes.

use axum::http::header;
use connectrpc::{ConnectError, Context, ErrorCode};

use crate::auth::{Claims, claims_from_bearer_header};
use crate::routes::AppState;

pub mod auth;
pub mod build;
pub mod cache;
pub mod gc;

/// Decodes required JWT claims from a ConnectRPC request context.
///
/// # Errors
///
/// Returns an `unauthenticated` error if the `Authorization` header is
/// missing, not valid ASCII, or does not carry a valid bearer JWT.
pub(crate) fn require_rpc_claims(ctx: &Context, state: &AppState) -> Result<Claims, ConnectError> {
    let auth_header = ctx
        .header(&header::AUTHORIZATION)
        .ok_or_else(|| {
            ConnectError::new(ErrorCode::Unauthenticated, "missing Authorization header")
        })?
        .to_str()
        .map_err(|_| {
            ConnectError::new(
                ErrorCode::Unauthenticated,
                "invalid Authorization header encoding",
            )
        })?;

    claims_from_bearer_header(auth_header, &state.jwt_secret)
        .map_err(|e| ConnectError::new(ErrorCode::Unauthenticated, e.to_string()))
}

/// Requires a valid JWT that grants access to `view`.
///
/// # Errors
///
/// Returns an `unauthenticated` error for a missing/invalid JWT, or
/// `permission_denied` if the claims do not cover the view.
pub(crate) fn require_rpc_view(
    ctx: &Context,
    state: &AppState,
    view: &str,
) -> Result<Claims, ConnectError> {
    let claims = require_rpc_claims(ctx, state)?;
    if !claims.has_view(view) {
        return Err(ConnectError::new(
            ErrorCode::PermissionDenied,
            "view not authorized",
        ));
    }
    Ok(claims)
}

/// Requires a valid JWT that grants access to `view` and `permission`.
///
/// # Errors
///
/// Returns an `unauthenticated` error for a missing/invalid JWT, or
/// `permission_denied` if the claims lack the view or the permission.
pub(crate) fn require_rpc_permission(
    ctx: &Context,
    state: &AppState,
    view: &str,
    permission: &str,
) -> Result<(), ConnectError> {
    let claims = require_rpc_view(ctx, state, view)?;
    if !claims.has_permission(permission) {
        return Err(ConnectError::new(
            ErrorCode::PermissionDenied,
            format!("{permission} permission required"),
        ));
    }
    Ok(())
}

/// Requires read access unless the view is configured for anonymous reads.
///
/// When `anonymous_read` is `true` this is a no-op; otherwise the JWT must
/// cover the view and include the `read` permission. Note this is stricter
/// than the REST extractors, which accept any valid JWT for reads.
///
/// # Errors
///
/// Returns an `unauthenticated` error for a missing/invalid JWT, or
/// `permission_denied` if the claims lack the view or `read` permission.
pub(crate) fn require_rpc_read_access(
    ctx: &Context,
    state: &AppState,
    view: &str,
    anonymous_read: bool,
) -> Result<(), ConnectError> {
    if anonymous_read {
        return Ok(());
    }

    let claims = require_rpc_view(ctx, state, view)?;
    if !claims.has_permission("read") {
        return Err(ConnectError::new(
            ErrorCode::PermissionDenied,
            "read permission required",
        ));
    }
    Ok(())
}
